# ==============================================================================
# Nginx Virtual Host Configuration for drshafaeiclinic.ir & www.drshafaeiclinic.ir
# Upstream: Gunicorn WSGI running on 127.0.0.1:5000
# Deployment Target: /etc/nginx/sites-available/drshafaeiclinic.ir
# ==============================================================================

server {
    listen 80;
    listen [::]:80;
    server_name drshafaeiclinic.ir www.drshafaeiclinic.ir;

    client_max_body_size 10M;

    # Static assets caching
    location /static/ {
        alias /root/psychology_bot/static/;
        expires 30d;
        add_header Cache-Control "public, no-transform";
    }

    # Deny direct access to private uploads
    location /private_uploads/ {
        deny all;
        return 404;
    }

    # Proxy all requests to Gunicorn Flask WSGI
    location / {
        proxy_pass http://127.0.0.1:5000;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_read_timeout 90s;
        proxy_connect_timeout 60s;
        proxy_redirect off;
    }
}

