            flash("تعداد دفعات ورود ناموفق بیش از حد مجاز است. لطفاً ۵ دقیقه بعد مجدداً تلاش فرمایید.", "danger")
            return render_template('admin_login.html'), 429

        password = request.form.get('password', '')
