                else:
                    logger.error(f"Telegram sendMessage fallback returned HTTP {res_msg.status_code} for admin {admin}: {res_msg.text}")
            except Exception as e_msg:
                logger.error(f"Error sending fallback text to admin {admin}: {e_msg}")

def send_receipt_to_telegram(app_id, name_with_phone, date, time, session_type, filepath, async_send=None):
    if async_send is None:
        async_send = not app.config.get('TESTING')
    if async_send:
        t = threading.Thread(
            target=_do_send_receipt_to_telegram,
            args=(app_id, name_with_phone, date, time, session_type, filepath),
            daemon=True
        )
        t.start()
        return t
    else:
        return _do_send_receipt_to_telegram(app_id, name_with_phone, date, time, session_type, filepath)

