import os
import re

def scan_sql_injections():
    sql_patterns = [r'\.execute\s*\(', r'\.executemany\s*\(']
    dynamic_indicators = ['f"', "f'", '%', '.format', '+', 'concat']

    for fname in ['app.py', 'database.py', 'daily_report.py']:
        with open(fname, 'r', encoding='utf-8') as f:
            lines = f.readlines()
        for idx, line in enumerate(lines, 1):
            if any(re.search(p, line) for p in sql_patterns):
                # Check line itself and subsequent lines if multi-line
                context = "".join(lines[max(0, idx-1):min(len(lines), idx+3)])
                if any(ind in context for ind in ['f"', "f'", '%s', '.format', ' + ']):
                    print(f"[SQL Dynamic] {fname}:{idx}: {line.strip()}")

scan_sql_injections()

